"                                 <button
                                    key={item.name}
                                    onClick={() => {
                                       const info = getReportPermissionInfo(item.name);
                                       if (info) {
                                          checkPermissionAndExecute(info.section, info.key, `${item.name}`, () => {
                                             setSelectedReport(item.name);
                                          });
                                       } else {
                                          setSelectedReport(item.name);
                                       }
                                    }}"
